可以按两种场景写：

1. 只是让用户拍照/录像：优先用系统 cameraPicker，代码更少。
2. 要在应用内显示预览、拍照、扫码或录像：用 Camera Kit。基本流程是：声明 CAMERA 权限 -> 运行时申请权限 -> 获取 CameraManager -> 创建 CameraInput 和 PreviewOutput/PhotoOutput -> 配置并启动 Session。

最小骨架如下：

```json
// module.json5
"requestPermissions": [
  { "name": "ohos.permission.CAMERA" }
]
```

```ts
import { camera } from '@kit.CameraKit';
import { common } from '@kit.AbilityKit';

let input: camera.CameraInput | undefined;
let session: camera.CaptureSession | undefined;
let preview: camera.PreviewOutput | undefined;

export async function startCamera(ctx: common.UIAbilityContext, surfaceId: string) {
  const manager = camera.getCameraManager(ctx);
  const device = manager.getSupportedCameras()[0];

  input = manager.createCameraInput(device);
  await input.open();

  const capability = manager.getSupportedOutputCapability(device, camera.SceneMode.NORMAL_PHOTO);
  preview = manager.createPreviewOutput(capability.previewProfiles[0], surfaceId);

  session = manager.createCaptureSession();
  session.beginConfig();
  session.addInput(input);
  session.addOutput(preview);
  await session.commitConfig();
  await session.start();
}

export async function stopCamera() {
  await session?.stop();
  session?.release();
  input?.close();
  preview?.release();
}
```

如果这是仓颉鸿蒙工程，通常把 Camera Kit 能力封装在 ArkTS 模块里，再由仓颉侧调用；如果你只是想“拍照并拿到图片路径”，应改用 cameraPicker 的更短写法。

